tasks.starter:
# CI (works): signs + attests, then deploys
- run: cosign sign --yes ghcr.io/acme/app@${DIGEST}
- run: cosign attest --predicate provenance.json --type slsaprovenance ghcr.io/acme/app@${DIGEST}
- run: kubectl set image deploy/api api=ghcr.io/acme/app@${DIGEST}

# Cluster: (nothing) — no admission policy installed.
# Problem: nothing verifies at deploy; an unsigned image deployed around CI runs.
